import 'package:flutter/material.dart';
import 'package:intl/intl.dart';
import '../../core/data/customer_repository.dart';
import '../../core/data/transaction_repository.dart';
import '../../shared/irkop_ui.dart';
class CustomersPage extends StatefulWidget{const CustomersPage({super.key,this.businessId});final String? businessId;@override State<CustomersPage> createState()=>_CustomersPageState();}
class _CustomersPageState extends State<CustomersPage>{final _repo=CustomerRepository();late Future<List<Customer>> _future;String _query='';@override void initState(){super.initState();_future=_load();}Future<List<Customer>> _load()=>widget.businessId==null?Future.value(const[]):_repo.loadCustomers(widget.businessId!);Future<void> _refresh()async{setState(()=>_future=_load());await _future;}
Future<void> _edit([Customer? x])async{final b=widget.businessId;if(b==null)return;final n=TextEditingController(text:x?.name??''),p=TextEditingController(text:x?.phone??'');final ok=await showModalBottomSheet<bool>(context:context,isScrollControlled:true,builder:(c)=>Padding(padding:EdgeInsets.fromLTRB(16,16,16,MediaQuery.of(c).viewInsets.bottom+16),child:Column(mainAxisSize:MainAxisSize.min,children:[Text(x==null?'Tambah Pelanggan':'Edit Pelanggan',style:Theme.of(c).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.w800)),const SizedBox(height:14),TextField(controller:n,textCapitalization:TextCapitalization.words,decoration:const InputDecoration(labelText:'Nama pelanggan')),const SizedBox(height:10),TextField(controller:p,keyboardType:TextInputType.phone,decoration:const InputDecoration(labelText:'Nomor telepon')),const SizedBox(height:14),SizedBox(width:double.infinity,child:FilledButton.icon(onPressed:()=>Navigator.pop(c,true),icon:const Icon(Icons.save_outlined),label:const Text('Simpan')))])));if(ok==true&&n.text.trim().isNotEmpty){try{if(x==null){await _repo.createCustomer(businessId:b,name:n.text,phone:p.text);}else{await _repo.updateCustomer(id:x.id,businessId:b,name:n.text,phone:p.text);}await _refresh();if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Data pelanggan disimpan.')));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Gagal: '+e.toString())));}}n.dispose();p.dispose();}
Future<void> _delete(Customer x)async{final b=widget.businessId;if(b==null)return;final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('Hapus pelanggan?'),content:Text(x.name+' akan dihapus dari data pelanggan.'),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Batal')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Hapus'))]));if(ok==true){try{await _repo.deleteCustomer(id:x.id,businessId:b);await _refresh();}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Gagal: '+e.toString())));}}}
Future<void> _detail(Customer x)async{final b=widget.businessId;if(b==null)return;List<TransactionSummary> h=const [];try{h=await _repo.history(businessId:b,customerId:x.id);}catch(_){}if(!mounted)return;final m=NumberFormat.currency(locale:'id_ID',symbol:'Rp ',decimalDigits:0),total=h.where((e)=>e.status=='completed').fold<double>(0,(s,e)=>s+e.total);await showModalBottomSheet<void>(context:context,isScrollControlled:true,builder:(c)=>SafeArea(child:DraggableScrollableSheet(expand:false,initialChildSize:.75,maxChildSize:.92,builder:(c,sc)=>ListView(controller:sc,padding:const EdgeInsets.all(20),children:[Row(children:[CircleAvatar(radius:28,child:Text(x.name.isEmpty?'P':x.name[0].toUpperCase())),const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(x.name,style:Theme.of(c).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.w800)),Text(x.phone??'Tanpa nomor telepon')]))]),const SizedBox(height:18),Row(children:[Expanded(child:_Metric(label:'Transaksi',value:h.length.toString())),const SizedBox(width:10),Expanded(child:_Metric(label:'Total Belanja',value:m.format(total)))]),const SizedBox(height:20),Text('Riwayat Transaksi',style:Theme.of(c).textTheme.titleMedium?.copyWith(fontWeight:FontWeight.w800)),const SizedBox(height:8),if(h.isEmpty)const EmptyStateCard(icon:Icons.receipt_long_outlined,title:'Belum ada transaksi',subtitle:'Riwayat pembelian pelanggan akan muncul di sini.'),...h.take(20).map((e)=>Card(child:ListTile(title:Text(e.transactionNo),subtitle:Text(e.paymentMethod+' • '+DateFormat('dd/MM/yy HH:mm').format(e.transactionAt.toLocal())),trailing:Text(m.format(e.total),style:const TextStyle(fontWeight:FontWeight.w700)))))]))));}
@override Widget build(BuildContext c)=>FutureBuilder<List<Customer>>(future:_future,builder:(c,s){final all=s.data??const <Customer>[],d=all.where((x)=>x.name.toLowerCase().contains(_query.toLowerCase())||(x.phone??'').contains(_query)).toList();return RefreshIndicator(onRefresh:_refresh,child:ListView(padding:const EdgeInsets.fromLTRB(16,12,16,28),children:[IrkopSectionHeader(eyebrow:'Database pelanggan',title:'Pelanggan',subtitle:all.length.toString()+' pelanggan tersimpan dan siap dipilih saat transaksi.',icon:Icons.people_outline,action:'Tambah',onAction:()=>_edit()),const SizedBox(height:14),TextField(onChanged:(v)=>setState(()=>_query=v),decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Cari nama atau nomor telepon')),const SizedBox(height:12),if(s.connectionState!=ConnectionState.done)const LinearProgressIndicator(),if(s.hasError)Card(child:Padding(padding:const EdgeInsets.all(16),child:Text('Gagal memuat pelanggan: '+s.error.toString()))),if(!s.hasError&&s.connectionState==ConnectionState.done&&d.isEmpty)const EmptyStateCard(icon:Icons.people_outline,title:'Belum ada pelanggan',subtitle:'Tambahkan pelanggan baru untuk mempercepat transaksi.'),...d.map((x)=>Card(child:ListTile(onTap:()=>_detail(x),leading:CircleAvatar(child:Text(x.name.isEmpty?'P':x.name[0].toUpperCase())),title:Text(x.name,style:const TextStyle(fontWeight:FontWeight.w800)),subtitle:Text((x.phone??'').isEmpty?'Tanpa nomor telepon':x.phone!),trailing:MenuAnchor(builder:(c,ctl,ch)=>IconButton(onPressed:()=>ctl.isOpen?ctl.close():ctl.open(),icon:const Icon(Icons.more_vert)),menuChildren:[MenuItemButton(onPressed:()=>_edit(x),leadingIcon:const Icon(Icons.edit_outlined),child:const Text('Edit')),MenuItemButton(onPressed:()=>_delete(x),leadingIcon:const Icon(Icons.delete_outline),child:const Text('Hapus'))]))))]));});}
